-- Add common process/activity titles to the global FMEA catalog so search works for process names as well as job titles.
ON DUPLICATE KEY UPDATE
  `titleFa` = VALUES(`titleFa`),
  `titleEn` = VALUES(`titleEn`),
  `keywords` = VALUES(`keywords`),
  `departmentFa` = VALUES(`departmentFa`),
  `departmentEn` = VALUES(`departmentEn`),
  `equipment` = VALUES(`equipment`),
  `materials` = VALUES(`materials`),
  `controls` = VALUES(`controls`),
  `active` = TRUE,
  `updatedAt` = CURRENT_TIMESTAMP(3);
